package breaketernity;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Random;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

/**
 * ECMAScript number-formatting/parsing compatibility. Every expected string in this file
 * was verified against Node (V8) - see also the differential test, which replays a much
 * larger corpus generated by the same Node process.
 */
class JsNumberTest {

    @ParameterizedTest
    @CsvSource({
        "1e21, 1e+21",
        "1e20, 100000000000000000000",
        "1e-6, 0.000001",
        "1e-7, 1e-7",
        "100, 100",
        "0.5, 0.5",
        "123.456, 123.456",
        "1e100, 1e+100",
        "5e-324, 5e-324",
        "1.7976931348623157e308, 1.7976931348623157e+308",
        "9007199254740991, 9007199254740991",
        "9007199254740992, 9007199254740992",
        "0.000001, 0.000001",
    })
    void toStringMatchesV8(double value, String expected) {
        assertEquals(expected, JsNumber.toString(value));
    }

    @Test
    void toStringSpecialValues() {
        assertEquals("NaN", JsNumber.toString(Double.NaN));
        assertEquals("Infinity", JsNumber.toString(Double.POSITIVE_INFINITY));
        assertEquals("-Infinity", JsNumber.toString(Double.NEGATIVE_INFINITY));
        // -0.0 prints as "0" in JS
        assertEquals("0", JsNumber.toString(-0.0));
        assertEquals("0", JsNumber.toString(0.0));
        assertEquals("-0.5", JsNumber.toString(-0.5));
    }

    @ParameterizedTest
    @CsvSource({
        "-0.5, 0, -1",
        "0.5, 0, 1",
        "1.5, 0, 2",
        "2.5, 0, 3",
        "1.005, 2, 1.00",
        "0.615, 2, 0.61",
        "-0.4, 0, -0",
        "-0.0001, 2, -0.00",
        "100, 2, 100.00",
        "1e21, 3, 1e+21",
    })
    void toFixedMatchesV8(double value, int places, String expected) {
        assertEquals(expected, JsNumber.toFixed(value, places));
    }

    @ParameterizedTest
    @CsvSource({
        "2.5, 0, 3e+0",
        "-2.5, 0, -3e+0",
        "1.005, 2, 1.00e+0",
        "0, 2, 0.00e+0",
        "1e21, 3, 1.000e+21",
        "123.456, 1, 1.2e+2",
    })
    void toExponentialMatchesV8(double value, int places, String expected) {
        assertEquals(expected, JsNumber.toExponential(value, places));
    }

    @Test
    void parseFloatPrefixSemantics() {
        assertEquals(1.0, JsNumber.parseFloat("1e"));
        assertEquals(1.0, JsNumber.parseFloat("1e+"));
        assertEquals(0.5, JsNumber.parseFloat(".5"));
        assertEquals(0.5, JsNumber.parseFloat("+.5"));
        assertEquals(5.0, JsNumber.parseFloat("5."));
        assertEquals(1.5, JsNumber.parseFloat("1.5abc"));
        assertEquals(1.2, JsNumber.parseFloat("1.2.3"));
        assertEquals(0.0, JsNumber.parseFloat("0x10"));
        assertEquals(12.0, JsNumber.parseFloat("  12  "));
        assertEquals(1.0, JsNumber.parseFloat("1,000"));
        assertEquals(Double.POSITIVE_INFINITY, JsNumber.parseFloat("Infinity"));
        assertEquals(Double.NEGATIVE_INFINITY, JsNumber.parseFloat("-Infinity"));
        assertEquals(Double.POSITIVE_INFINITY, JsNumber.parseFloat("1e999"));
        assertEquals(0.0, JsNumber.parseFloat("1e-999"));
        assertTrue(Double.isNaN(JsNumber.parseFloat("")));
        assertTrue(Double.isNaN(JsNumber.parseFloat("abc")));
        assertTrue(Double.isNaN(JsNumber.parseFloat("-")));
    }

    @Test
    void roundMatchesEcmaScriptMathRound() {
        assertEquals(-0.0, JsNumber.round(-0.5));
        assertEquals(1.0, JsNumber.round(0.5));
        assertEquals(3.0, JsNumber.round(2.5));
        assertEquals(-2.0, JsNumber.round(-2.5));
        assertEquals(0.0, JsNumber.round(0.49999999999999994));
        // identity at and beyond 2^52 (Java's Math.round would return a saturated long)
        assertEquals(5536577221694931.0, JsNumber.round(5536577221694931.0));
        assertEquals(1e300, JsNumber.round(1e300));
    }

    @Test
    void truncMatchesEcmaScriptMathTrunc() {
        assertEquals(-0.0, JsNumber.trunc(-0.5));
        assertEquals(0.0, JsNumber.trunc(0.5));
        assertEquals(-2.0, JsNumber.trunc(-2.5));
        assertEquals(2.0, JsNumber.trunc(2.5));
        assertEquals(1e300, JsNumber.trunc(1e300));
    }

    /** toString must round-trip exactly for random doubles (shortest representation). */
    @Test
    void toStringRoundTrips() {
        Random rng = new Random(99);
        for (int i = 0; i < 20000; i++) {
            double value = Double.longBitsToDouble(rng.nextLong());
            if (Double.isNaN(value)) {
                continue;
            }
            double parsed = Double.parseDouble(JsNumber.toString(value));
            assertEquals(
                    Double.doubleToRawLongBits(value),
                    Double.doubleToRawLongBits(parsed),
                    "round trip failed for " + value);
        }
    }

    /** The shortest representation must never be longer than 17 significant digits. */
    @Test
    void shortestRepresentationLength() {
        Random rng = new Random(100);
        for (int i = 0; i < 20000; i++) {
            double value = Double.longBitsToDouble(rng.nextLong());
            if (Double.isNaN(value) || Double.isInfinite(value) || value == 0) {
                continue;
            }
            String s = JsNumber.toString(Math.abs(value));
            // Count only the mantissa digits, not the exponent's.
            int exponentAt = s.indexOf('e');
            String mantissa = exponentAt < 0 ? s : s.substring(0, exponentAt);
            // Count significant digits: strip the decimal point, then leading and
            // trailing zeros (so "86166548336529570000" counts 17, and "0.0074" counts 2).
            String digitChars = mantissa.replace(".", "");
            int start = 0;
            while (start < digitChars.length() - 1 && digitChars.charAt(start) == '0') {
                start++;
            }
            int end = digitChars.length();
            while (end > start + 1 && digitChars.charAt(end - 1) == '0') {
                end--;
            }
            int digits = digitChars.substring(start, end).length();
            assertTrue(digits <= 17, "too many digits (" + digits + ") for " + s);
        }
    }
}
